import {METRICS} from '../../core/statistics.js';
import {esc,fmt} from '../../ui/format.js';
export function statisticsView(result){
 if(!result.summary)return '';
 const level=result.confidence??.95;
 const interval=s=>s?.confidence?.lower==null?'Unavailable':`${fmt(s.confidence.lower,4)} ... ${fmt(s.confidence.upper,4)}`;
 return `<section class="panel tablewrap"><h2>Statistici intre replicari</h2><p>All replications: mean, sample standard deviation, min/max and ${(level*100).toFixed(1)}% Student-t confidence interval for the mean. One replication cannot estimate uncertainty. Undefined ratios are excluded and their count is shown; this can bias cost per good when zero-output runs occur. Ratio intervals are not clipped to [0,1].</p>${(result.warnings||[]).map(w=>`<div class="notice">${esc(w)}</div>`).join('')}<p>Lead time uses only parts completed in the observation window, including their full age from arrival. Unfinished WIP at horizon (mean): <b>${fmt(result.summary.wip.mean)}</b>. Warm-up: ${result.window?.warmupSeconds||0} s; no automatic deletion of an empty shift start.</p><table><thead><tr><th>Indicator / unit</th><th>Mean</th><th>Std</th><th>CI ${(level*100).toFixed(1)}%</th><th>Min / max</th><th>N valid / all</th></tr></thead><tbody>${Object.entries(METRICS).map(([k,[label,unit]])=>{const s=result.summary[k];return s?`<tr><td>${esc(label)} (${unit})</td><td>${fmt(s.mean,4)}</td><td>${fmt(s.std,4)}</td><td>${interval(s)}</td><td>${fmt(s.min,4)} / ${fmt(s.max,4)}</td><td>${s.n} / ${s.total??s.n}</td></tr>`:'';}).join('')}</tbody></table><h3>Utilization across all replications</h3><p>Resource utilization means reserved capacity; operation utilization means processing capacity.</p><table><thead><tr><th>Entity / ratio</th><th>Mean</th><th>Std</th><th>CI</th><th>Min / max</th><th>N</th></tr></thead><tbody>${Object.entries(result.utilization||{}).flatMap(([group,entities])=>Object.entries(entities).map(([id,s])=>`<tr><td>${esc(group)} / ${esc(id)}</td><td>${fmt(s.mean,4)}</td><td>${fmt(s.std,4)}</td><td>${interval(s)}</td><td>${fmt(s.min,4)} / ${fmt(s.max,4)}</td><td>${s.n}</td></tr>`)).join('')}</tbody></table><p>FPY pools first completed attempts across stations. Observed RTY is good terminal units with no rework divided by all terminal units, not a product of station yields for a fixed routing. Rework load is busy seconds on repeat station visits. Scrap rate excludes unfinished units. Inspect denominators and each run in JSON; these estimates are not factory-calibrated recommendations.</p></section>`;
}
